77	     * (o null). Condiviso da AttributesEditor::reactive() e OrphanAttributesAlert.
78	     *
79	     * @return \Closure(Get): ?AttributeSchema
80	     */
81	    private static function schemaResolver(): \Closure
82	    {
83	        return static function (Get $get): ?AttributeSchema {
84	            $class = self::schemaClassFor($get('product_type_id'));
85	
86	            return $class !== null ? new $class() : null;
87	        };
88	    }
89	
90	    /**
91	     * FQN della AttributeSchema associata a una tipologia, o null se non risolvibile.
92	     *
93	     * @return class-string<AttributeSchema>|null
94	     */
95	    private static function schemaClassFor(mixed $productTypeId): ?string
96	    {
97	        if (! is_numeric($productTypeId)) {
98	            return null;
99	        }
100	
101	        $class = ProductType::query()->find((int) $productTypeId)?->attribute_schema_class;
102	
103	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
104	    }
